scripts.build:
node --input-type=module -e 'const sender=process.env.GESTORIA_OWNER_EMAIL, recipient=process.env.GESTORIA_ALTERNATE_EMAIL, key=process.env.BREVO_API_KEY;
const reason=s=>/unrecogni.ed ip|unauthori.ed ip|ip address.*(allowed|authori.ed)/i.test(s)?'"'"'ip_restricted'"'"':/sender|domain/i.test(s)?'"'"'sender_or_domain'"'"':/api key/i.test(s)?'"'"'api_key'"'"':/block|suppression|blacklist/i.test(s)?'"'"'blocked'"'"':/spam|policy|dmarc|spf|dkim/i.test(s)?'"'"'mail_policy'"'"':/quota|credit|limit/i.test(s)?'"'"'quota_or_limit'"'"':/suspend|account/i.test(s)?'"'"'account'"'"':s?'"'"'other'"'"':'"'"'none'"'"';
console.log('"'"'MG_DELIVERY_DIAG env'"'"',JSON.stringify({sender:!!sender,recipient:!!recipient,key:!!key}));
const checks=[];
if(key&&sender&&recipient){checks.push(...[
['"'"'sender'"'"','"'"'https://api.brevo.com/v3/senders'"'"'],
['"'"'events'"'"','"'"'https://api.brevo.com/v3/smtp/statistics/events?'"'"'+new URLSearchParams({email:recipient,days:'"'"'1'"'"',limit:'"'"'20'"'"'})],
].map(async ([name,url])=>{try{
 const res=await fetch(url,{headers:{'"'"'api-key'"'"':key},signal:AbortSignal.timeout(10000)});
 const body=await res.json();
 const data=name==='"'"'sender'"'"'?{configuredSenderActive:body.senders?.some(x=>x.email?.toLowerCase()===sender.toLowerCase()&&x.active===true),activeSenders:body.senders?.filter(x=>x.active===true).length}:{events:body.events?.map(x=>({event:x.event,reason:reason(x.reason)}))};
 console.log('"'"'MG_DELIVERY_DIAG '"'"'+name,JSON.stringify({status:res.status,reason:reason(body.message),...data}));
}catch(e){console.log('"'"'MG_DELIVERY_DIAG '"'"'+name,JSON.stringify({failed:true,error:e.name}));}}));}
checks.push((async()=>{try{
 const {get}=await import('"'"'@vercel/blob'"'"');
 const blob=await get('"'"'mi-gestoria/personal/v1/access.json'"'"',{access:'"'"'private'"'"',useCache:false});
 const data=blob&&await new Response(blob.stream).json();
 const now=Date.now();
 console.log('"'"'MG_DELIVERY_DIAG blob'"'"',JSON.stringify({exists:!!blob,attemptsPastHour:data?.sent?.filter(n=>now-n<3600000).length,minutesSinceAttempt:data?.sent?.length?Math.floor((now-data.sent.at(-1))/60000):null}));
}catch(e){console.log('"'"'MG_DELIVERY_DIAG blob'"'"',JSON.stringify({failed:true,error:e.name,reason:/credential|token/i.test(e.message)?'"'"'credentials'"'"':/forbidden|authori.ed/i.test(e.message)?'"'"'forbidden'"'"':'"'"'other'"'"'}));}})());
await Promise.all(checks);
process.exit(1);'
